        alu_op <= io_in_bits_alu_op;
        rs1_data <= io_in_bits_rs1_data;
        rs2_data <= io_in_bits_rs2_data;
        csr_rdata <= io_in_bits_csr_rdata;
        pc <= io_in_bits_pc;
        rd_addr <= io_in_bits_rd_addr;
        rd_en <= io_in_bits_rd_en;
        csr_wdata <= io_in_bits_csr_wdata;
        csr_wen <= io_in_bits_csr_wen;
        csr_waddr <= io_in_bits_csr_waddr;
        is_csrrw <= io_in_bits_is_csrrw;
        is_csrrs <= io_in_bits_is_csrrs;
        is_lw <= io_in_bits_is_lw;
        is_lbu <= io_in_bits_is_lbu;
        is_lh <= io_in_bits_is_lh;
        is_lhu <= io_in_bits_is_lhu;
        is_lb <= io_in_bits_is_lb;
        is_sw <= io_in_bits_is_sw;
        is_sb <= io_in_bits_is_sb;
        is_sh <= io_in_bits_is_sh;
        is_jalr <= io_in_bits_is_jalr;
        is_jal <= io_in_bits_is_jal;
        is_ecall <= io_in_bits_is_ecall;
        is_mret <= io_in_bits_is_mret;
        is_beq <= io_in_bits_is_beq;
        is_bne <= io_in_bits_is_bne;
        is_blt <= io_in_bits_is_blt;
        is_bltu <= io_in_bits_is_bltu;
        is_bge <= io_in_bits_is_bge;
        is_bgeu <= io_in_bits_is_bgeu;
      end
    end
  end // always @(posedge)
  ALU alu (
    .io_a     (alu_a),
    .io_b     (alu_b),
    .io_aluOp (alu_op),
    .io_out   (io_out_bits_alu_result)
  );
  assign io_in_ready = ~state;
  assign io_out_valid = out_valid;
  assign io_out_bits_pc = pc;
  assign io_out_bits_rs2_data = rs2_data;
  assign io_out_bits_rd_addr = rd_addr;
  assign io_out_bits_rd_en = rd_en;
  assign io_out_bits_csr_wdata = csr_wdata;
  assign io_out_bits_csr_wen = csr_wen;
  assign io_out_bits_csr_waddr = csr_waddr;
  assign io_out_bits_csr_rdata = csr_rdata;
  assign io_out_bits_is_csrrw = is_csrrw;
  assign io_out_bits_is_csrrs = is_csrrs;
  assign io_out_bits_is_lw = is_lw;
  assign io_out_bits_is_lbu = is_lbu;
  assign io_out_bits_is_lh = is_lh;
  assign io_out_bits_is_lhu = is_lhu;
  assign io_out_bits_is_lb = is_lb;
  assign io_out_bits_is_sw = is_sw;
  assign io_out_bits_is_sb = is_sb;
  assign io_out_bits_is_sh = is_sh;
  assign io_out_bits_is_jalr = is_jalr;
  assign io_out_bits_is_jal = is_jal;
  assign io_branch_valid = out_valid;
  assign io_branch_bits_pc_branch = _pc_jal_T;
  assign io_branch_bits_pc_jal = _pc_jal_T;
  assign io_branch_bits_pc_jalr = {_pc_jalr_T[31:1], 1'h0};
  assign io_branch_bits_is_branch_taken =
    is_beq
      ? rs1_data == rs2_data
      : is_bne
          ? rs1_data != rs2_data
          : is_blt
              ? $signed(rs1_data) < $signed(rs2_data)
              : is_bltu
                  ? rs1_data < rs2_data
                  : is_bge
                      ? $signed(rs1_data) >= $signed(rs2_data)
                      : is_bgeu & rs1_data >= rs2_data;
  assign io_branch_bits_is_jal = is_jal;
  assign io_branch_bits_is_jalr = is_jalr;
  assign io_branch_bits_is_ecall = is_ecall;
  assign io_branch_bits_is_mret = is_mret;
  assign io_branch_bits_pc_csr = csr_rdata;
endmodule

module MEM1(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_alu_result,
                io_in_bits_rs2_data,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_en,
  input  [31:0] io_in_bits_csr_wdata,
  input         io_in_bits_csr_wen,
  input  [11:0] io_in_bits_csr_waddr,
  input  [31:0] io_in_bits_csr_rdata,
  input         io_in_bits_is_csrrw,
                io_in_bits_is_csrrs,
                io_in_bits_is_lw,
                io_in_bits_is_lbu,
                io_in_bits_is_lh,
                io_in_bits_is_lhu,
                io_in_bits_is_lb,
                io_in_bits_is_sw,
                io_in_bits_is_sb,
                io_in_bits_is_sh,
                io_in_bits_is_jalr,
                io_in_bits_is_jal,
                io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_pc,
                io_out_bits_addr,
  output [4:0]  io_out_bits_rd_addr,
  output        io_out_bits_rd_en,
  output [31:0] io_out_bits_csr_wdata,
  output        io_out_bits_csr_wen,
  output [11:0] io_out_bits_csr_waddr,
  output [31:0] io_out_bits_csr_rdata,
  output        io_out_bits_is_csrrw,
                io_out_bits_is_csrrs,
                io_out_bits_is_load,
                io_out_bits_is_store,
                io_out_bits_is_lb,
                io_out_bits_is_lbu,
                io_out_bits_is_lh,
                io_out_bits_is_lhu,
                io_out_bits_is_jalr,
                io_out_bits_is_jal,
  input         io_mem_req_ready,
  output        io_mem_req_valid,
                io_mem_req_bits_wen,
  output [31:0] io_mem_req_bits_wdata,
  output [3:0]  io_mem_req_bits_wmask,
  output [31:0] io_mem_req_bits_raddr,
                io_mem_req_bits_waddr,
  output        io_mem_req_bits_bypass
);

  reg  [31:0] pc;
  reg  [31:0] alu_result;
  reg  [31:0] rs2_data;
  reg  [4:0]  rd_addr;
  reg         rd_en;
  reg  [31:0] csr_wdata;
  reg         csr_wen;
  reg  [11:0] csr_waddr;
  reg  [31:0] csr_rdata;
  reg         is_csrrw;
  reg         is_csrrs;
  reg         is_lbu;
  reg         is_lh;
  reg         is_lhu;
  reg         is_lb;
  reg         is_sw;
  reg         is_sb;
  reg         is_sh;
  reg         is_jalr;
  reg         is_jal;
  reg         is_load;
  reg         is_store;
  reg  [1:0]  state;
  wire        in_ready = state == 2'h0;
  reg         req_sent;
  reg         out_sent;
  wire        _GEN = state == 2'h1;
  wire        io_mem_req_valid_0 = ~in_ready & _GEN & ~req_sent;
  wire        _GEN_0 = state == 2'h2;
  wire        io_out_valid_0 = ~in_ready & (_GEN ? req_sent & ~out_sent : _GEN_0);
  wire [38:0] _wdata_T_2 = {31'h0, rs2_data[7:0]} << {34'h0, alu_result[1:0], 3'h0};
  wire [46:0] _wdata_T_5 = {31'h0, rs2_data[15:0]} << {42'h0, alu_result[1], 4'h0};
  wire        _GEN_1 = in_ready & io_in_valid;
  wire        _GEN_2 =
    io_in_bits_is_lw | io_in_bits_is_lb | io_in_bits_is_lbu | io_in_bits_is_lh
    | io_in_bits_is_lhu | io_in_bits_is_sw | io_in_bits_is_sb | io_in_bits_is_sh;
  wire        _GEN_3 = _GEN_1 & _GEN_2;
  wire        _GEN_4 = io_out_ready & io_out_valid_0;
  always @(posedge clock) begin
    if (reset) begin
      pc <= 32'h0;
      alu_result <= 32'h0;
      rs2_data <= 32'h0;
      rd_addr <= 5'h0;
      rd_en <= 1'h0;
      csr_wdata <= 32'h0;
      csr_wen <= 1'h0;
      csr_waddr <= 12'h0;
      csr_rdata <= 32'h0;
      is_csrrw <= 1'h0;
      is_csrrs <= 1'h0;
      is_lbu <= 1'h0;
      is_lh <= 1'h0;
      is_lhu <= 1'h0;
      is_lb <= 1'h0;
      is_sw <= 1'h0;
      is_sb <= 1'h0;
      is_sh <= 1'h0;
      is_jalr <= 1'h0;
      is_jal <= 1'h0;
      is_load <= 1'h0;
      is_store <= 1'h0;
      state <= 2'h0;
      req_sent <= 1'h0;
      out_sent <= 1'h0;
    end
    else begin
      if (_GEN_1) begin
        pc <= io_in_bits_pc;
        alu_result <= io_in_bits_alu_result;
        rs2_data <= io_in_bits_rs2_data;
        rd_addr <= io_in_bits_rd_addr;
        rd_en <= io_in_bits_rd_en;
        csr_wdata <= io_in_bits_csr_wdata;
        csr_wen <= io_in_bits_csr_wen;
        csr_waddr <= io_in_bits_csr_waddr;
        csr_rdata <= io_in_bits_csr_rdata;
        is_csrrw <= io_in_bits_is_csrrw;
        is_csrrs <= io_in_bits_is_csrrs;
        is_lbu <= io_in_bits_is_lbu;
        is_lh <= io_in_bits_is_lh;
        is_lhu <= io_in_bits_is_lhu;
        is_lb <= io_in_bits_is_lb;
        is_sw <= io_in_bits_is_sw;
        is_sb <= io_in_bits_is_sb;
        is_sh <= io_in_bits_is_sh;
        is_jalr <= io_in_bits_is_jalr;
        is_jal <= io_in_bits_is_jal;
        is_load <=
          io_in_bits_is_lw | io_in_bits_is_lb | io_in_bits_is_lbu | io_in_bits_is_lh
          | io_in_bits_is_lhu;
        is_store <= io_in_bits_is_sw | io_in_bits_is_sb | io_in_bits_is_sh;
      end
      if (in_ready) begin
        if (_GEN_1)
          state <= _GEN_2 ? 2'h1 : 2'h2;
      end
      else if (_GEN ? req_sent & out_sent : _GEN_0 & _GEN_4)
        state <= 2'h0;
      req_sent <=
        in_ready
          ? ~_GEN_3 & req_sent
          : _GEN & io_mem_req_ready & io_mem_req_valid_0 | req_sent;
      out_sent <= in_ready ? ~_GEN_3 & out_sent : _GEN & _GEN_4 | out_sent;
    end
  end // always @(posedge)
  assign io_in_ready = in_ready;
  assign io_out_valid = io_out_valid_0;
  assign io_out_bits_pc = pc;
  assign io_out_bits_addr = alu_result;
  assign io_out_bits_rd_addr = rd_addr;
  assign io_out_bits_rd_en = rd_en;
  assign io_out_bits_csr_wdata = csr_wdata;
  assign io_out_bits_csr_wen = csr_wen;
  assign io_out_bits_csr_waddr = csr_waddr;
  assign io_out_bits_csr_rdata = csr_rdata;
  assign io_out_bits_is_csrrw = is_csrrw;
  assign io_out_bits_is_csrrs = is_csrrs;
  assign io_out_bits_is_load = is_load;
  assign io_out_bits_is_store = is_store;
  assign io_out_bits_is_lb = is_lb;
  assign io_out_bits_is_lbu = is_lbu;
  assign io_out_bits_is_lh = is_lh;
  assign io_out_bits_is_lhu = is_lhu;
  assign io_out_bits_is_jalr = is_jalr;
  assign io_out_bits_is_jal = is_jal;
  assign io_mem_req_valid = io_mem_req_valid_0;
  assign io_mem_req_bits_wen = is_sw | is_sh | is_sb;
  assign io_mem_req_bits_wdata =
    is_sb ? _wdata_T_2[31:0] : is_sh ? _wdata_T_5[31:0] : is_sw ? rs2_data : 32'h0;
  assign io_mem_req_bits_wmask =
    is_sb ? 4'h1 << alu_result[1:0] : is_sh ? (alu_result[1] ? 4'hC : 4'h3) : {4{is_sw}};
  assign io_mem_req_bits_raddr = alu_result;
  assign io_mem_req_bits_waddr = alu_result;
  assign io_mem_req_bits_bypass =
    is_store & alu_result[31:26] != 6'h28 | pc < 32'hA0010000 & (is_load | is_store);
endmodule

module MEM2(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_addr,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_en,
  input  [31:0] io_in_bits_csr_wdata,
  input         io_in_bits_csr_wen,
  input  [11:0] io_in_bits_csr_waddr,
  input  [31:0] io_in_bits_csr_rdata,
  input         io_in_bits_is_csrrw,
                io_in_bits_is_csrrs,
                io_in_bits_is_load,
                io_in_bits_is_store,
                io_in_bits_is_lb,
                io_in_bits_is_lbu,
                io_in_bits_is_lh,
                io_in_bits_is_lhu,
                io_in_bits_is_jalr,
                io_in_bits_is_jal,
                io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_pc,
                io_out_bits_addr,
  output [4:0]  io_out_bits_rd_addr,
  output        io_out_bits_rd_en,
  output [31:0] io_out_bits_mem_data,
  output        io_out_bits_is_load,
                io_out_bits_is_jalr,
                io_out_bits_is_jal,
  output [31:0] io_out_bits_csr_wdata,
  output        io_out_bits_csr_wen,
  output [11:0] io_out_bits_csr_waddr,
  output [31:0] io_out_bits_csr_rdata,
  output        io_out_bits_is_csrrw,
                io_out_bits_is_csrrs,
                io_mem_resp_ready,
  input         io_mem_resp_valid,
  input  [31:0] io_mem_resp_bits_addr,
                io_mem_resp_bits_data
);

  reg  [1:0]  state;
  reg  [31:0] pc;
  reg  [31:0] addr;
  reg  [4:0]  rd_addr;
  reg         rd_en;
  reg         is_load;
  reg         is_lb;
  reg         is_lbu;
  reg         is_lh;
  reg         is_lhu;
  reg         is_jalr;
  reg         is_jal;
  reg  [31:0] csr_wdata;
  reg         csr_wen;
  reg  [11:0] csr_waddr;
  reg  [31:0] csr_rdata;
  reg         is_csrrw;
  reg         is_csrrs;
  reg  [31:0] mem_data;
  wire        io_in_ready_0 = state == 2'h0;
  wire        _GEN = state == 2'h1;
  wire        io_mem_resp_ready_0 = ~io_in_ready_0 & _GEN;
  reg  [7:0]  casez_tmp;
  always_comb begin
    casez (io_mem_resp_bits_addr[1:0])
      2'b00:
        casez_tmp = io_mem_resp_bits_data[7:0];
      2'b01:
        casez_tmp = io_mem_resp_bits_data[15:8];
      2'b10:
        casez_tmp = io_mem_resp_bits_data[23:16];
      default:
        casez_tmp = io_mem_resp_bits_data[31:24];
    endcase
  end // always_comb
  wire        _GEN_0 = state == 2'h2;
  wire        io_out_valid_0 = ~(io_in_ready_0 | _GEN) & _GEN_0;
  wire        _GEN_1 = io_in_bits_is_load | io_in_bits_is_store;
  wire [15:0] halfData =
    io_mem_resp_bits_addr[1] ? io_mem_resp_bits_data[31:16] : io_mem_resp_bits_data[15:0];
  wire        _GEN_2 = io_mem_resp_ready_0 & io_mem_resp_valid;
  wire        _GEN_3 = io_in_ready_0 & io_in_valid;
  always @(posedge clock) begin
    if (reset) begin
      state <= 2'h0;
      pc <= 32'h0;
      addr <= 32'h0;
      rd_addr <= 5'h0;
      rd_en <= 1'h0;
      is_load <= 1'h0;
      is_lb <= 1'h0;
      is_lbu <= 1'h0;
      is_lh <= 1'h0;
      is_lhu <= 1'h0;
      is_jalr <= 1'h0;
      is_jal <= 1'h0;
      csr_wdata <= 32'h0;
      csr_wen <= 1'h0;
      csr_waddr <= 12'h0;
      csr_rdata <= 32'h0;
      is_csrrw <= 1'h0;
      is_csrrs <= 1'h0;
      mem_data <= 32'h0;
    end
    else begin
      if (io_in_ready_0) begin
        if (_GEN_3) begin
          state <= _GEN_1 ? 2'h1 : 2'h2;
          addr <= io_in_bits_addr;
        end
        if (~_GEN_3 | _GEN_1) begin
        end
        else
          mem_data <= 32'h0;
      end
      else begin
        if (_GEN) begin
          if (_GEN_2)
            state <= 2'h2;
        end
        else if (_GEN_0 & io_out_ready & io_out_valid_0)
          state <= 2'h0;
        if (_GEN & _GEN_2) begin
          addr <= io_mem_resp_bits_addr;
          mem_data <=
            is_load
              ? (is_lbu
                   ? {24'h0, casez_tmp}
                   : is_lb
                       ? {{24{casez_tmp[7]}}, casez_tmp}
                       : is_lhu
                           ? {16'h0, halfData}
                           : is_lh
                               ? {{16{halfData[15]}}, halfData}
                               : io_mem_resp_bits_data)
              : io_mem_resp_bits_data;
        end
      end
      if (_GEN_3) begin
        pc <= io_in_bits_pc;
        rd_addr <= io_in_bits_rd_addr;
        rd_en <= io_in_bits_rd_en;
        is_load <= io_in_bits_is_load;
        is_lb <= io_in_bits_is_lb;
        is_lbu <= io_in_bits_is_lbu;
        is_lh <= io_in_bits_is_lh;
        is_lhu <= io_in_bits_is_lhu;
        is_jalr <= io_in_bits_is_jalr;
        is_jal <= io_in_bits_is_jal;
        csr_wdata <= io_in_bits_csr_wdata;
        csr_wen <= io_in_bits_csr_wen;
        csr_waddr <= io_in_bits_csr_waddr;
        csr_rdata <= io_in_bits_csr_rdata;
        is_csrrw <= io_in_bits_is_csrrw;
        is_csrrs <= io_in_bits_is_csrrs;
      end
    end
  end // always @(posedge)
  assign io_in_ready = io_in_ready_0;
  assign io_out_valid = io_out_valid_0;
  assign io_out_bits_pc = pc;
  assign io_out_bits_addr = addr;
  assign io_out_bits_rd_addr = rd_addr;
  assign io_out_bits_rd_en = rd_en;
  assign io_out_bits_mem_data = mem_data;
  assign io_out_bits_is_load = is_load;
  assign io_out_bits_is_jalr = is_jalr;
  assign io_out_bits_is_jal = is_jal;
  assign io_out_bits_csr_wdata = csr_wdata;
  assign io_out_bits_csr_wen = csr_wen;
  assign io_out_bits_csr_waddr = csr_waddr;
  assign io_out_bits_csr_rdata = csr_rdata;
  assign io_out_bits_is_csrrw = is_csrrw;
  assign io_out_bits_is_csrrs = is_csrrs;
  assign io_mem_resp_ready = io_mem_resp_ready_0;
endmodule

module WB(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_pc,
                io_in_bits_addr,
  input  [4:0]  io_in_bits_rd_addr,
  input         io_in_bits_rd_en,
  input  [31:0] io_in_bits_mem_data,
  input         io_in_bits_is_load,
                io_in_bits_is_jalr,
                io_in_bits_is_jal,
  input  [31:0] io_in_bits_csr_wdata,
  input         io_in_bits_csr_wen,
  input  [11:0] io_in_bits_csr_waddr,
  input  [31:0] io_in_bits_csr_rdata,
  input         io_in_bits_is_csrrw,
                io_in_bits_is_csrrs,
  output [4:0]  io_rd_addr,
  output [31:0] io_rd_data,
  output        io_rd_en,
  output [11:0] io_csr_waddr,
  output [31:0] io_csr_wdata,
  output        io_csr_wen,
                io_commit
);

  wire        io_in_ready_0;
  reg  [31:0] pc;
  reg  [31:0] addr;
  reg  [4:0]  rd_addr;
  reg         rd_en;
  reg  [31:0] mem_data;
  reg         is_load;
  reg         is_jalr;
  reg         is_jal;
  reg  [31:0] csr_wdata;
  reg         csr_wen;
  reg  [11:0] csr_waddr;
  reg  [31:0] csr_rdata;
  reg         is_csrrw;
  reg         is_csrrs;
  wire        _GEN = io_in_ready_0 & io_in_valid;
  reg  [1:0]  state;
  assign io_in_ready_0 = state == 2'h0;
  reg  [1:0]  casez_tmp;
  always_comb begin
    casez (state)
      2'b00:
        casez_tmp = _GEN ? 2'h1 : state;
      2'b01:
        casez_tmp = 2'h2;
      2'b10:
        casez_tmp = 2'h0;
      default:
        casez_tmp = state;
    endcase
  end // always_comb
  always @(posedge clock) begin
    if (reset) begin
      pc <= 32'h0;
      addr <= 32'h0;
      rd_addr <= 5'h0;
      rd_en <= 1'h0;
      mem_data <= 32'h0;
      is_load <= 1'h0;
      is_jalr <= 1'h0;
      is_jal <= 1'h0;
      csr_wdata <= 32'h0;
      csr_wen <= 1'h0;
      csr_waddr <= 12'h0;
      csr_rdata <= 32'h0;
      is_csrrw <= 1'h0;
      is_csrrs <= 1'h0;
      state <= 2'h0;
    end
    else begin
      if (_GEN) begin
        pc <= io_in_bits_pc;
        addr <= io_in_bits_addr;
        rd_addr <= io_in_bits_rd_addr;
        rd_en <= io_in_bits_rd_en;
        mem_data <= io_in_bits_mem_data;
        is_load <= io_in_bits_is_load;
        is_jalr <= io_in_bits_is_jalr;
        is_jal <= io_in_bits_is_jal;
        csr_wdata <= io_in_bits_csr_wdata;
        csr_wen <= io_in_bits_csr_wen;
        csr_waddr <= io_in_bits_csr_waddr;
        csr_rdata <= io_in_bits_csr_rdata;
        is_csrrw <= io_in_bits_is_csrrw;
        is_csrrs <= io_in_bits_is_csrrs;
      end
      state <= casez_tmp;
    end
  end // always @(posedge)
  assign io_in_ready = io_in_ready_0;
  assign io_rd_addr = rd_addr;
  assign io_rd_data =
    is_csrrw | is_csrrs
      ? csr_rdata
      : is_load ? mem_data : is_jal | is_jalr ? pc + 32'h4 : addr;
  assign io_rd_en = rd_en;
  assign io_csr_waddr = csr_waddr;
  assign io_csr_wdata = csr_wdata;
  assign io_csr_wen = csr_wen;
  assign io_commit = state == 2'h2;
endmodule

module MaxPeriodFibonacciLFSR(
  input  clock,
         reset,
  output io_out_0,
         io_out_1,
         io_out_2,
         io_out_3,
         io_out_4,
         io_out_5,
         io_out_6,
         io_out_7
);

  reg state_0;
  reg state_1;
  reg state_2;
  reg state_3;
  reg state_4;
  reg state_5;
  reg state_6;
  reg state_7;
  always @(posedge clock) begin
    if (reset) begin
      state_0 <= 1'h1;
      state_1 <= 1'h0;
      state_2 <= 1'h0;
      state_3 <= 1'h0;
      state_4 <= 1'h0;
      state_5 <= 1'h0;
      state_6 <= 1'h0;
      state_7 <= 1'h0;
    end
    else begin
      state_0 <= state_7 ^ state_5 ^ state_4 ^ state_3;
      state_1 <= state_0;
      state_2 <= state_1;
      state_3 <= state_2;
      state_4 <= state_3;
      state_5 <= state_4;
      state_6 <= state_5;
      state_7 <= state_6;
    end
  end // always @(posedge)
  assign io_out_0 = state_0;
  assign io_out_1 = state_1;
  assign io_out_2 = state_2;
  assign io_out_3 = state_3;
  assign io_out_4 = state_4;
  assign io_out_5 = state_5;
  assign io_out_6 = state_6;
  assign io_out_7 = state_7;
endmodule

