  output [31:0] io_csr_rdata,
  input  [11:0] io_csr_waddr,
  input  [31:0] io_csr_wdata,
  input         io_csr_wen,
                io_is_ecall,
                io_is_mret
);

  reg  [31:0] mtvec;
  reg  [31:0] mepc;
  reg  [31:0] mcause;
  reg  [31:0] mstatus;
